// 24-S3 acceptance: the editor's confirmed state and pending operations
// (`outbox.ts`). Pure. Do not edit this file to match an implementation.
import { describe, expect, it } from 'vitest';
import { createGrid, withLetter, type Grid } from '@/engine/grid';
import { serializeGrid } from '@/lib/puzzle-storage';
import type { PuzzleContent } from './apply';
import type { Operation, OperationBody } from './operation';
import {
  cellWrites, enqueue, hintChanges, makeOperation, projectOutbox, rebaseView, settle, titleChange, type Outbox,
} from './outbox';

function letters(grid: Grid, entries: Array<[number, number, string]>): Grid {
  return entries.reduce((next, [col, row, letter]) => withLetter(next, { col, row }, letter), grid);
}
const blank = createGrid({ cols: 5, rows: 5 });
const cat = letters(blank, [[0, 0, 'C'], [1, 0, 'A'], [2, 0, 'T']]);
const content = (grid: Grid, extra: Partial<PuzzleContent> = {}): PuzzleContent => ({
  grid: serializeGrid(grid), hints: {}, title: 'Mini', phase: 'grid', ...extra,
});
const outbox = (base: PuzzleContent = content(cat), version = 4, resetEpoch = 2): Outbox => ({
  confirmed: { content: base, version, resetEpoch }, pending: [],
});
let counter = 0;
const ids = () => ({ opId: `op-${++counter}`, puzzleId: 'p', clientId: 'tab' });
const add = (box: Outbox, body: OperationBody): [Outbox, Operation] => {
  const op = makeOperation(box, body, ids());
  return [enqueue(box, op), op];
};
const letterAt = (c: PuzzleContent, col: number, row: number) => {
  const cell = c.grid.cells[row][col];
  return cell.kind === 'active' ? cell.letter : 'black';
};

describe('24-S3-1 confirmed state plus pending operations', () => {
  it('makes operations against the confirmed version, in the epoch the pending ones lead to', () => {
    let box = outbox();
    const [afterCells, cells] = add(box, { kind: 'cells', writes: [{ col: 0, row: 1, value: 'X' }] });
    expect(cells).toMatchObject({ puzzleId: 'p', clientId: 'tab', epoch: 2, baseVersion: 4, kind: 'cells' });
    box = afterCells;
    const [afterReset, reset] = add(box, { kind: 'startOver', keepLockedWords: false });
    expect(reset.epoch).toBe(2);
    const [, after] = add(afterReset, { kind: 'title', title: 'Later' });
    expect(after.epoch).toBe(3);
    expect(after.baseVersion).toBe(4);
  });

  it('projects the pending operations, in order, onto the confirmed state without changing it', () => {
    const start = outbox();
    const frozen = JSON.stringify(start);
    let [box] = add(start, { kind: 'cells', writes: [{ col: 0, row: 0, value: 'B' }] });
    [box] = add(box, { kind: 'cells', writes: [{ col: 0, row: 0, value: 'H' }, { col: 3, row: 0, value: 'S' }] });
    [box] = add(box, { kind: 'title', title: '  Renamed  ' });
    const projected = projectOutbox(box);
    expect(letterAt(projected.content, 0, 0)).toBe('H');
    expect(letterAt(projected.content, 3, 0)).toBe('S');
    expect(projected.content.title).toBe('Renamed');
    expect(projected.resetEpoch).toBe(2);
    expect(JSON.stringify(start)).toBe(frozen);
    expect(letterAt(box.confirmed.content, 0, 0)).toBe('C');
  });

  it('leaves out of the projection a pending operation that would not fit', () => {
    let [box] = add(outbox(), { kind: 'hint', key: '1-across', text: 'In Build' });
    [box] = add(box, { kind: 'cells', writes: [{ col: 4, row: 4, value: 'Z' }] });
    const projected = projectOutbox(box).content;
    expect(projected.hints).toEqual({});
    expect(letterAt(projected, 4, 4)).toBe('Z');
  });

  it('follows a pending Start Over into its new epoch', () => {
    const [box] = add(outbox(), { kind: 'startOver', keepLockedWords: false });
    const projected = projectOutbox(box);
    expect(projected.resetEpoch).toBe(3);
    expect(letterAt(projected.content, 0, 0)).toBeNull();
  });
});

describe('24-S3-2 settling an operation', () => {
  it('an acceptance applies it to the confirmed state at its version and drops it', () => {
    const [box, op] = add(outbox(), { kind: 'cells', writes: [{ col: 3, row: 0, value: 'S' }] });
    const settled = settle(box, op.opId, { status: 'accepted', version: 5 });
    expect(settled.pending).toEqual([]);
    expect(settled.confirmed.version).toBe(5);
    expect(letterAt(settled.confirmed.content, 3, 0)).toBe('S');
    expect(letterAt(box.confirmed.content, 3, 0)).toBeNull();
  });

  it('an acceptance of a structural operation follows its epoch', () => {
    const [box, op] = add(outbox(), { kind: 'startOver', keepLockedWords: false });
    const settled = settle(box, op.opId, { status: 'accepted', version: 5 });
    expect(settled.confirmed.resetEpoch).toBe(3);
    expect(letterAt(settled.confirmed.content, 0, 0)).toBeNull();
  });

  it('an acceptance at or below the confirmed version (a resend that had landed) is not applied again', () => {
    const base = content(letters(cat, [[0, 0, 'B']]));
    const [box, op] = add(outbox(base, 7), { kind: 'cells', writes: [{ col: 0, row: 0, value: 'H' }] });
    for (const version of [3, 7]) {
      const settled = settle(box, op.opId, { status: 'accepted', version });
      expect(settled.pending).toEqual([]);
      expect(settled.confirmed).toBe(box.confirmed);
    }
  });

  it('a refusal drops it without touching the confirmed state; later ones stay in order', () => {
    let [box, first] = add(outbox(), { kind: 'cells', writes: [{ col: 0, row: 0, value: 'X' }] });
    let second: Operation;
    [box, second] = add(box, { kind: 'title', title: 'Kept' });
    const settled = settle(box, first.opId, { status: 'refused', code: 'locked' });
    expect(settled.confirmed).toBe(box.confirmed);
    expect(settled.pending).toEqual([second]);
    expect(letterAt(projectOutbox(settled).content, 0, 0)).toBe('C');
  });

  it('an unknown opId changes nothing', () => {
    const [box] = add(outbox(), { kind: 'title', title: 'X' });
    expect(settle(box, 'nope', { status: 'accepted', version: 9 })).toBe(box);
  });
});

describe('24-S3-3 what a burst writes', () => {
  it('only the cells the view changed, row-major; the same letter again is no change', () => {
    const base = serializeGrid(cat);
    const view = serializeGrid(letters(cat, [[2, 0, 'T'], [0, 0, 'B'], [4, 1, 'Q']]));
    expect(cellWrites(base, view)).toEqual([{ col: 0, row: 0, value: 'B' }, { col: 4, row: 1, value: 'Q' }]);
    expect(cellWrites(base, serializeGrid(letters(cat, [[1, 0, 'A']])))).toEqual([]);
  });

  it('clears and rebuses; black cells and locks are not cell writes', () => {
    const base = serializeGrid(cat, [{ col: 0, row: 0, orientation: 'across', length: 3 }]);
    const view = serializeGrid(letters(withLetter(cat, { col: 1, row: 0 }, null), [[3, 3, 'OW']]));
    expect(cellWrites(base, view)).toEqual([{ col: 1, row: 0, value: null }, { col: 3, row: 3, value: 'OW' }]);
    const blackened = serializeGrid(createGrid({ cols: 5, rows: 5, black: [{ col: 4, row: 4 }, { col: 0, row: 0 }] }));
    expect(cellWrites(serializeGrid(blank), blackened)).toEqual([]);
  });

  it('hints by key with their whole text; the title compared as the server stores it', () => {
    expect(hintChanges({ '1-across': 'Old', '2-down': 'Same' }, { '1-across': 'New', '2-down': 'Same', '3-down': '' }))
      .toEqual([{ key: '1-across', text: 'New' }, { key: '3-down', text: '' }]);
    expect(titleChange('Mini', '  Mini ')).toBeNull();
    expect(titleChange('Mini', 'Maxi ')).toBe('Maxi ');
    expect(titleChange('Untitled Puzzle', '   ')).toBeNull();
  });

  it('rebasing keeps the draft over the new base and takes everything else from it', () => {
    const oldBase = content(letters(cat, [[0, 1, 'X']]), { hints: { '1-across': 'a' }, title: 'Old' });
    const view = content(letters(cat, [[0, 1, 'X'], [4, 4, 'D']]), { hints: { '1-across': 'draft' }, title: 'Old' });
    const newBase = content(cat, { hints: { '1-across': 'a', '2-down': 'b' }, title: 'New' });
    const rebased = rebaseView(oldBase, view, newBase);
    expect(letterAt(rebased, 0, 1)).toBeNull();
    expect(letterAt(rebased, 4, 4)).toBe('D');
    expect(rebased.hints).toEqual({ '1-across': 'draft', '2-down': 'b' });
    expect(rebased.title).toBe('New');
    expect(letterAt(view, 0, 1)).toBe('X');
  });
});
